import heapq

def dijkstra(graph, start):
    heap = [(0, start)]
    distances = {start: 0}

    while heap:
        (d, current) = heapq.heappop(heap)

        if current in distances:
            continue

        distances[current] = d
        for neighbor, weight in graph[current].items():
            if neighbor not in distances or distances[neighbor] > distances[current] + weight:
                heapq.heappush(heap, (distances[current] + weight, neighbor))

    return distances

def solve():
    t = int(input())
    for _ in range(t):
        n, x = map(int, input().split())
        graph = {}
        for i in range(1, n+1):
            a_i = int(input())
            if i != 0 and i != x:
                graph[i] = {}
                graph[i][x + i - a_i] = 1
                graph[a_i] = {i: 1}
                if i < x:
                    graph[-(x + i - a_i)] = {i: 1}
                if a_i < x:
                    graph[-a_i] = {-i: 1}
        fuel_needed = dijkstra(graph, x) - 2 * dijkstra(graph, -x)
