from itertools import combinations
import sys

def solve(n, k, x):
    if n < x or n > k * (k - 1) // 2 + k:
        return "NO"

    sets = [set([i for i in range(1, k+1) if i != x])]
    comb_len = len(combinations(sets[0], n - (k - 1)))

    for s in combinations(sets, n // (k - 1)):
        comb_len *= len(s[0]) ** (n // (k - 1))

    if comb_len < k ** (n - 1):
        return "NO"

    sets.append(combinations(sets[0], n // (k - 1)))
    for i in range(2, n // (k - 1) + 1):
        temporary = []
        for combo_i in sets[-1-i]:
            for combo_j in sets[-i:]:
                temporary.append(list(set.union(*[combo_i, combo_j])))
        sets.append(temporary)

    result = []
    i = n - k + 1
    while i > 0:
        if i >= len(sets[-1]):
            i -= len(sets[-1])
            continue
        for set_ in sets[::-1]:
            if i in set_[i]:
                result.append((set_[i][i]))
                i = 0
                break
        else:
            i -= 1

    result.sort()
    return "\n".join(str(x) for x in [len(result), *result])

if __name__ == "__main__":
