        prefix_sum[i] = prefix_sum[i - 1] + arr[i - 1]
        abs_prefix_diff[i] = abs_diff(prefix_sum[i], prefix_sum[i - 1])

    # Calculate the partial sums of the multiples of GCD for each index.
    gcd_val = gcd(-max(arr), max(arr))
    dp = [[0] * n for _ in range(gcd_val + 1)]
    for i in range(n):
        for j in range(gcd_val + 1):
            if arr[i] == 0:
                dp[0][i] = abs_prefix_diff[i]
            else:
                for k in range(min(j, gcd_val // abs(arr[i])) - 1, -1, -1):
                    dp[k + 1][i] = max(dp[k + 1][i], dp[k][i] + dp[abs(arr[i]) * (k + 1)][i - abs(arr[i]) * (k + 1)])
