            if i < 1 or i == n or j < 1 or j == m:
                return
            board[i][j] = steps + 1
            fill_corner(i+2, j-1, steps+1)
            fill_corner(i+2, j+1, steps+1)
            fill_corner(i-2, j-1, steps+1)
            fill_corner(i-2, j+1, steps+1)

        # Fill the rest of the board with zigzag patterns to mark cells that are reachable from corners
        def fill_zigzag(x0, y0, steps=3):
            if x0 < 1 or x0 == n-1 or y0 < 1 or y0 == m-1:
                return
            directions = [(-1,-2), (-1,2), (1,-2), (1,2)]
            for dx, dy in directions:
                board[(x0+steps*dx) % n][(y0+steps*dy) % m] = steps + 1

            fill_zigzag(x0+dx, y0+dy, steps+1)

        # Fill the corners first, then the zigzags
        for i in range(1, n-1):
            for j in range(1, m-1):
                board[i][j] = min([fill_corner(i, j, -1), fill_zigzag(i, j, -1)])

        # Find any cells with max value, which are the isolated cells
        xs = []
        ys = []
        max_val = board[0][0]
        for i in range(n):
            for j in range(m):
                if board[i][j] > max_val:
                    max_val = board[i][j]
                    xs, ys = [i], [j]
