import heapq

def dijkstra(graph):
    distances = {node: float('inf') for node in graph}
    distances[0] = 0
    priority_queue = [(0, 0)]

    while priority_queue:
        (len_of_chain, current) = heapq.heappop(priority_ queue)

        if current == len(graph) - 1:
            return distances[current]

        for neighbor in graph[current]:
