from math import sqrt, gcd
import functools

def extend(f):
    @functools.wraps(f)
    def _extend(*args, **kwargs):
        result = f(*args, **kwargs)
        for i in range(len(result) - 1, 0, -1):
            result[i:] = list(itertools.accumulate(result[i:]))
        return result[::-1]
    return _extend

@extend
def cumsum(numbers):
    return [sum(numbers[i:j]) for i, j in zip([0], itertools.accumulate([0] + list(reversed(map(ord, numbers)))))]

def solve(N, M):
    arr = [''.join(str(i) for i in range(1, M + 1)) for _ in range(M * N)]

    def get_dominoes():
        dms = set()
        for i in range(len(arr)):
            for j in range(len(arr[0])):
                if i + 2 < len(arr) and arr[i][j] != arr[i+1][j]:
                    continue
                left, right = cumsum([ord(c) - ord('1') for c in (arr[(i or 0)][:j]) if c != '.']),  cumsum([ord(c) - ord('1') for c in arr[min(i+N, len(arr))][j:] if c != '.'])
                dms.add((left, right))
        return list(map(lambda x: (min(x), max(x)), unique([gcd(*dm) for dm in dms])) if M & 1 else dms)

    return len(list(itertools.product(*get_dominoes())))

if __name__ == "__main__":
    N, M = map(int, input().split())
    print(solve(N, M))
```

